-- A review survey for existing admins only. This is not a general push API.
-- The same publication validators apply to this fixture and future authored surveys.
create function private.install_example_survey(creator uuid) returns uuid
language plpgsql security definer set search_path = '' as $$
declare sample_id uuid := 'e2000000-0000-4000-8000-000000000001';
  assignment_id uuid; push_id uuid; item jsonb; question_id uuid; country_options jsonb;
begin
  perform pg_advisory_xact_lock(72130501002);
  if not exists (select 1 from private.admin_memberships where user_id=creator) then
    raise exception 'Example setup requires an admin' using errcode='42501';
  end if;
  if not exists (select 1 from public.surveys where id=sample_id) then
    insert into public.surveys(id,title,description,reward_points,created_by)
      values (sample_id,'Everyday life, your way','Tell us about your everyday habits, favorite products, and the choices that matter to you.',100,creator);
    for item in select value from jsonb_array_elements($definition$[
      {"key":"age","section":"demographics","type":"integer","presentation":"number_input","prompt":"How old are you?","config":{"version":1,"min":0,"max":120,"allow_decline":true}},
      {"key":"income_bracket","section":"demographics","type":"single_choice","presentation":"dropdown","prompt":"What is your personal monthly income (INR)?","config":{"version":1,"options":[{"id":"under_25000","label":"Under ₹25,000 per month"},{"id":"25000_49999","label":"₹25,000–₹49,999 per month"},{"id":"50000_99999","label":"₹50,000–₹99,999 per month"},{"id":"100000_plus","label":"₹100,000 or more per month"},{"id":"not_applicable","label":"Not applicable / income in another currency"},{"id":"prefer_not_to_say","label":"Prefer not to say"}]}},
      {"key":"marital_status","section":"demographics","type":"single_choice","presentation":"radio_cards","prompt":"What is your marital status?","config":{"version":1,"options":[{"id":"single","label":"Single"},{"id":"married","label":"Married / civil partnership"},{"id":"separated","label":"Separated / divorced"},{"id":"widowed","label":"Widowed"},{"id":"prefer_not_to_say","label":"Prefer not to say"}]}},
      {"key":"country","section":"demographics","type":"single_choice","presentation":"dropdown","prompt":"Which country do you live in?","config":{"version":1,"options":[{"id":"IN","label":"India"},{"id":"US","label":"United States"},{"id":"GB","label":"United Kingdom"},{"id":"CA","label":"Canada"},{"id":"AU","label":"Australia"},{"id":"DE","label":"Germany"},{"id":"FR","label":"France"},{"id":"JP","label":"Japan"},{"id":"BR","label":"Brazil"},{"id":"ZA","label":"South Africa"},{"id":"prefer_not_to_say","label":"Prefer not to say"}]}},
      {"key":"social_media","section":"body","type":"single_choice","presentation":"radio_cards","prompt":"How much time do you spend on social media each day?","config":{"version":1,"options":[{"id":"none","label":"I don’t use social media"},{"id":"under_hour","label":"Less than an hour"},{"id":"one_three","label":"1–3 hours"},{"id":"three_plus","label":"More than 3 hours"}]}},
      {"key":"products_owned","section":"body","type":"multi_choice","presentation":"checkbox_cards","prompt":"Which of these do you currently own?","config":{"version":1,"min":1,"max":4,"exclusive_option_ids":["none"],"options":[{"id":"earbuds","label":"Wireless earbuds"},{"id":"watch","label":"Smartwatch / fitness tracker"},{"id":"tablet","label":"Tablet"},{"id":"console","label":"Gaming console"},{"id":"none","label":"None of these"}]}},
      {"key":"shopping_frequency","section":"body","type":"single_choice","presentation":"dropdown","prompt":"How often do you shop online?","config":{"version":1,"options":[{"id":"weekly","label":"At least once a week"},{"id":"monthly","label":"A few times a month"},{"id":"occasionally","label":"Every few months"},{"id":"never","label":"Rarely or never"}]}},
      {"key":"shopping_opinion","section":"body","type":"single_choice","presentation":"radio_cards","prompt":"I prefer paying more for products that last longer.","config":{"version":1,"options":[{"id":"agree","label":"Agree"},{"id":"neutral","label":"Neither agree nor disagree"},{"id":"disagree","label":"Disagree"}]}},
      {"key":"favorite_accessory","section":"body","type":"text","presentation":"short_text","prompt":"What is one accessory you use almost every day?","config":{"version":1,"min":1,"max":120}},
      {"key":"color_choice","section":"body","type":"single_choice","presentation":"radio_cards","prompt":"To show you’re reading this question, please select Blue.","config":{"version":1,"options":[{"id":"red","label":"Red"},{"id":"blue","label":"Blue"},{"id":"green","label":"Green"}]},"check":{"version":1,"operator":"equals_option","expected_option_id":"blue"}},
      {"key":"shopping_improvement","section":"body","type":"text","presentation":"long_text","prompt":"What would make your online shopping experience better?","required":false,"config":{"version":1,"min":1,"max":1000}}
    ]$definition$::jsonb) loop
      insert into public.survey_questions(survey_id,position,section,field_key,type,presentation,prompt,required,config)
        values (sample_id,(select count(*) from public.survey_questions where survey_id=sample_id),item->>'section',
          item->>'key',item->>'type',item->>'presentation',item->>'prompt',coalesce((item->>'required')::boolean,true),item->'config') returning id into question_id;
      if item ? 'check' then insert into private.question_checks(question_id,rule) values (question_id,item->'check'); end if;
    end loop;
    country_options := $countries$[{"id":"AF","label":"Afghanistan"},{"id":"AX","label":"Åland Islands"},{"id":"AL","label":"Albania"},{"id":"DZ","label":"Algeria"},{"id":"AS","label":"American Samoa"},{"id":"AD","label":"Andorra"},{"id":"AO","label":"Angola"},{"id":"AI","label":"Anguilla"},{"id":"AQ","label":"Antarctica"},{"id":"AG","label":"Antigua & Barbuda"},{"id":"AR","label":"Argentina"},{"id":"AM","label":"Armenia"},{"id":"AW","label":"Aruba"},{"id":"AU","label":"Australia"},{"id":"AT","label":"Austria"},{"id":"AZ","label":"Azerbaijan"},{"id":"BS","label":"Bahamas"},{"id":"BH","label":"Bahrain"},{"id":"BD","label":"Bangladesh"},{"id":"BB","label":"Barbados"},{"id":"BY","label":"Belarus"},{"id":"BE","label":"Belgium"},{"id":"BZ","label":"Belize"},{"id":"BJ","label":"Benin"},{"id":"BM","label":"Bermuda"},{"id":"BT","label":"Bhutan"},{"id":"BO","label":"Bolivia"},{"id":"BA","label":"Bosnia & Herzegovina"},{"id":"BW","label":"Botswana"},{"id":"BV","label":"Bouvet Island"},{"id":"BR","label":"Brazil"},{"id":"IO","label":"British Indian Ocean Territory"},{"id":"VG","label":"British Virgin Islands"},{"id":"BN","label":"Brunei"},{"id":"BG","label":"Bulgaria"},{"id":"BF","label":"Burkina Faso"},{"id":"BI","label":"Burundi"},{"id":"KH","label":"Cambodia"},{"id":"CM","label":"Cameroon"},{"id":"CA","label":"Canada"},{"id":"CV","label":"Cape Verde"},{"id":"BQ","label":"Caribbean Netherlands"},{"id":"KY","label":"Cayman Islands"},{"id":"CF","label":"Central African Republic"},{"id":"TD","label":"Chad"},{"id":"CL","label":"Chile"},{"id":"CN","label":"China"},{"id":"CX","label":"Christmas Island"},{"id":"CC","label":"Cocos (Keeling) Islands"},{"id":"CO","label":"Colombia"},{"id":"KM","label":"Comoros"},{"id":"CG","label":"Congo - Brazzaville"},{"id":"CD","label":"Congo - Kinshasa"},{"id":"CK","label":"Cook Islands"},{"id":"CR","label":"Costa Rica"},{"id":"CI","label":"Côte d’Ivoire"},{"id":"HR","label":"Croatia"},{"id":"CU","label":"Cuba"},{"id":"CW","label":"Curaçao"},{"id":"CY","label":"Cyprus"},{"id":"CZ","label":"Czechia"},{"id":"DK","label":"Denmark"},{"id":"DJ","label":"Djibouti"},{"id":"DM","label":"Dominica"},{"id":"DO","label":"Dominican Republic"},{"id":"EC","label":"Ecuador"},{"id":"EG","label":"Egypt"},{"id":"SV","label":"El Salvador"},{"id":"GQ","label":"Equatorial Guinea"},{"id":"ER","label":"Eritrea"},{"id":"EE","label":"Estonia"},{"id":"SZ","label":"Eswatini"},{"id":"ET","label":"Ethiopia"},{"id":"FK","label":"Falkland Islands (Islas Malvinas)"},{"id":"FO","label":"Faroe Islands"},{"id":"FJ","label":"Fiji"},{"id":"FI","label":"Finland"},{"id":"FR","label":"France"},{"id":"GF","label":"French Guiana"},{"id":"PF","label":"French Polynesia"},{"id":"TF","label":"French Southern Territories"},{"id":"GA","label":"Gabon"},{"id":"GM","label":"Gambia"},{"id":"GE","label":"Georgia"},{"id":"DE","label":"Germany"},{"id":"GH","label":"Ghana"},{"id":"GI","label":"Gibraltar"},{"id":"GR","label":"Greece"},{"id":"GL","label":"Greenland"},{"id":"GD","label":"Grenada"},{"id":"GP","label":"Guadeloupe"},{"id":"GU","label":"Guam"},{"id":"GT","label":"Guatemala"},{"id":"GG","label":"Guernsey"},{"id":"GN","label":"Guinea"},{"id":"GW","label":"Guinea-Bissau"},{"id":"GY","label":"Guyana"},{"id":"HT","label":"Haiti"},{"id":"HM","label":"Heard & McDonald Islands"},{"id":"HN","label":"Honduras"},{"id":"HK","label":"Hong Kong"},{"id":"HU","label":"Hungary"},{"id":"IS","label":"Iceland"},{"id":"IN","label":"India"},{"id":"ID","label":"Indonesia"},{"id":"IR","label":"Iran"},{"id":"IQ","label":"Iraq"},{"id":"IE","label":"Ireland"},{"id":"IM","label":"Isle of Man"},{"id":"IL","label":"Israel"},{"id":"IT","label":"Italy"},{"id":"JM","label":"Jamaica"},{"id":"JP","label":"Japan"},{"id":"JE","label":"Jersey"},{"id":"JO","label":"Jordan"},{"id":"KZ","label":"Kazakhstan"},{"id":"KE","label":"Kenya"},{"id":"KI","label":"Kiribati"},{"id":"KW","label":"Kuwait"},{"id":"KG","label":"Kyrgyzstan"},{"id":"LA","label":"Laos"},{"id":"LV","label":"Latvia"},{"id":"LB","label":"Lebanon"},{"id":"LS","label":"Lesotho"},{"id":"LR","label":"Liberia"},{"id":"LY","label":"Libya"},{"id":"LI","label":"Liechtenstein"},{"id":"LT","label":"Lithuania"},{"id":"LU","label":"Luxembourg"},{"id":"MO","label":"Macao"},{"id":"MG","label":"Madagascar"},{"id":"MW","label":"Malawi"},{"id":"MY","label":"Malaysia"},{"id":"MV","label":"Maldives"},{"id":"ML","label":"Mali"},{"id":"MT","label":"Malta"},{"id":"MH","label":"Marshall Islands"},{"id":"MQ","label":"Martinique"},{"id":"MR","label":"Mauritania"},{"id":"MU","label":"Mauritius"},{"id":"YT","label":"Mayotte"},{"id":"MX","label":"Mexico"},{"id":"FM","label":"Micronesia"},{"id":"MD","label":"Moldova"},{"id":"MC","label":"Monaco"},{"id":"MN","label":"Mongolia"},{"id":"ME","label":"Montenegro"},{"id":"MS","label":"Montserrat"},{"id":"MA","label":"Morocco"},{"id":"MZ","label":"Mozambique"},{"id":"MM","label":"Myanmar (Burma)"},{"id":"NA","label":"Namibia"},{"id":"NR","label":"Nauru"},{"id":"NP","label":"Nepal"},{"id":"NL","label":"Netherlands"},{"id":"NC","label":"New Caledonia"},{"id":"NZ","label":"New Zealand"},{"id":"NI","label":"Nicaragua"},{"id":"NE","label":"Niger"},{"id":"NG","label":"Nigeria"},{"id":"NU","label":"Niue"},{"id":"NF","label":"Norfolk Island"},{"id":"KP","label":"North Korea"},{"id":"MK","label":"North Macedonia"},{"id":"MP","label":"Northern Mariana Islands"},{"id":"NO","label":"Norway"},{"id":"OM","label":"Oman"},{"id":"PK","label":"Pakistan"},{"id":"PW","label":"Palau"},{"id":"PS","label":"Palestine"},{"id":"PA","label":"Panama"},{"id":"PG","label":"Papua New Guinea"},{"id":"PY","label":"Paraguay"},{"id":"PE","label":"Peru"},{"id":"PH","label":"Philippines"},{"id":"PN","label":"Pitcairn Islands"},{"id":"PL","label":"Poland"},{"id":"PT","label":"Portugal"},{"id":"PR","label":"Puerto Rico"},{"id":"QA","label":"Qatar"},{"id":"RE","label":"Réunion"},{"id":"RO","label":"Romania"},{"id":"RU","label":"Russia"},{"id":"RW","label":"Rwanda"},{"id":"WS","label":"Samoa"},{"id":"SM","label":"San Marino"},{"id":"ST","label":"São Tomé & Príncipe"},{"id":"SA","label":"Saudi Arabia"},{"id":"SN","label":"Senegal"},{"id":"RS","label":"Serbia"},{"id":"SC","label":"Seychelles"},{"id":"SL","label":"Sierra Leone"},{"id":"SG","label":"Singapore"},{"id":"SX","label":"Sint Maarten"},{"id":"SK","label":"Slovakia"},{"id":"SI","label":"Slovenia"},{"id":"SB","label":"Solomon Islands"},{"id":"SO","label":"Somalia"},{"id":"ZA","label":"South Africa"},{"id":"GS","label":"South Georgia & South Sandwich Islands"},{"id":"KR","label":"South Korea"},{"id":"SS","label":"South Sudan"},{"id":"ES","label":"Spain"},{"id":"LK","label":"Sri Lanka"},{"id":"BL","label":"St. Barthélemy"},{"id":"SH","label":"St. Helena"},{"id":"KN","label":"St. Kitts & Nevis"},{"id":"LC","label":"St. Lucia"},{"id":"MF","label":"St. Martin"},{"id":"PM","label":"St. Pierre & Miquelon"},{"id":"VC","label":"St. Vincent & Grenadines"},{"id":"SD","label":"Sudan"},{"id":"SR","label":"Suriname"},{"id":"SJ","label":"Svalbard & Jan Mayen"},{"id":"SE","label":"Sweden"},{"id":"CH","label":"Switzerland"},{"id":"SY","label":"Syria"},{"id":"TW","label":"Taiwan"},{"id":"TJ","label":"Tajikistan"},{"id":"TZ","label":"Tanzania"},{"id":"TH","label":"Thailand"},{"id":"TL","label":"Timor-Leste"},{"id":"TG","label":"Togo"},{"id":"TK","label":"Tokelau"},{"id":"TO","label":"Tonga"},{"id":"TT","label":"Trinidad & Tobago"},{"id":"TN","label":"Tunisia"},{"id":"TR","label":"Türkiye"},{"id":"TM","label":"Turkmenistan"},{"id":"TC","label":"Turks & Caicos Islands"},{"id":"TV","label":"Tuvalu"},{"id":"UM","label":"U.S. Outlying Islands"},{"id":"VI","label":"U.S. Virgin Islands"},{"id":"UG","label":"Uganda"},{"id":"UA","label":"Ukraine"},{"id":"AE","label":"United Arab Emirates"},{"id":"GB","label":"United Kingdom"},{"id":"US","label":"United States"},{"id":"UY","label":"Uruguay"},{"id":"UZ","label":"Uzbekistan"},{"id":"VU","label":"Vanuatu"},{"id":"VA","label":"Vatican City"},{"id":"VE","label":"Venezuela"},{"id":"VN","label":"Vietnam"},{"id":"WF","label":"Wallis & Futuna"},{"id":"EH","label":"Western Sahara"},{"id":"YE","label":"Yemen"},{"id":"ZM","label":"Zambia"},{"id":"ZW","label":"Zimbabwe"},{"id":"prefer_not_to_say","label":"Prefer not to say"}]$countries$::jsonb;
    update public.survey_questions set config=jsonb_build_object('version',1,'options',country_options)
      where survey_id=sample_id and field_key='country';
    update public.surveys set status='published',published_at=now() where id=sample_id;
  end if;
  select id into assignment_id from public.survey_assignments where survey_id=sample_id and user_id=creator;
  if assignment_id is not null then return assignment_id; end if;
  insert into public.survey_pushes(survey_id,audience,created_by,request_id,request_fingerprint,targeted_count,new_assignment_count)
    values (sample_id,'selected',creator,gen_random_uuid(),'phase-2-admin-example',1,1) returning id into push_id;
  insert into public.survey_push_targets(push_id,user_id) values (push_id,creator);
  insert into public.survey_assignments(survey_id,user_id,first_push_id) values (sample_id,creator,push_id) returning id into assignment_id;
  return assignment_id;
end;
$$;
revoke all on function private.install_example_survey(uuid) from public,anon,authenticated;
do $$ declare administrator record; begin
  for administrator in select user_id from private.admin_memberships loop
    perform private.install_example_survey(administrator.user_id);
  end loop;
end $$;
